{"files":[{"path":"daily_net.py","content":"import csv
import os
import sys
from datetime import datetime
from decimal import Decimal, InvalidOperation

REQUIRED = ["paid_at", "channel", "status", "amount", "refund_amount"]
ALLOWED_STATUS = {"PAID", "REFUNDED", "CANCELLED"}


class DataError(Exception):
    def __init__(self, line_no, field):
        self.line_no = line_no
        self.field = field
        super().__init__(f"line {line_no} field {field}")


def parse_amount(value, line_no, field):
    s = value.strip()
    if s == "":
        raise DataError(line_no, field)
    low = s.lower()
    if low in ("nan", "inf", "+inf", "-inf", "infinity", "+infinity", "-infinity"):
        raise DataError(line_no, field)
    try:
        d = Decimal(s)
    except (InvalidOperation, ValueError):
        raise DataError(line_no, field)
    if not d.is_finite():
        raise DataError(line_no, field)
    if d < 0:
        raise DataError(line_no, field)
    if d != d.quantize(Decimal("0.01")):
        raise DataError(line_no, field)
    return d


def parse_date(value, line_no):
    s = value.strip()
    if len(s) != 10:
        raise DataError(line_no, "paid_at")
    try:
        datetime.strptime(s, "%Y-%m-%d")
    except ValueError:
        raise DataError(line_no, "paid_at")
    return s


def main(argv):
    if len(argv) != 3:
        sys.stderr.write("usage: python daily_net.py input.csv output.csv\n")
        return 2
    in_path, out_path = argv[1], argv[2]
    if os.path.realpath(in_path) == os.path.realpath(out_path):
        sys.stderr.write("input and output paths are the same\n")
        return 2

    try:
        with open(in_path, "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.reader(f)
            try:
                header = next(reader)
            except StopIteration:
                sys.stderr.write("missing header\n")
                return 2
            header = [h.strip() for h in header]
            index = {}
            for name in REQUIRED:
                if name not in header:
                    sys.stderr.write(f"missing header field: {name}\n")
                    return 2
                index[name] = header.index(name)

            totals = {}
            line_no = 0
            for row in reader:
                line_no += 1
                if len(row) == 0:
                    continue
                if len(row) <= max(index.values()):
                    missing = None
                    for name in REQUIRED:
                        if index[name] >= len(row):
                            missing = name
                            break
                    raise DataError(line_no, missing or "row")

                status = row[index["status"]].strip()
                if status not in ALLOWED_STATUS:
                    raise DataError(line_no, "status")
                if status == "CANCELLED":
                    continue

                date = parse_date(row[index["paid_at"]], line_no)

                channel = row[index["channel"]].strip()
                if channel == "":
                    raise DataError(line_no, "channel")

                amount = parse_amount(row[index["amount"]], line_no, "amount")
                refund = parse_amount(row[index["refund_amount"]], line_no, "refund_amount")
                if refund > amount:
                    raise DataError(line_no, "refund_amount")

                net = amount - refund
                key = (date, channel)
                totals[key] = totals.get(key, Decimal("0")) + net
    except DataError as e:
        sys.stderr.write(f"data error at line {e.line_no}, field {e.field}\n")
        return 2
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        sys.stderr.write(f"input error: {e}\n")
        return 2

    try:
        with open(out_path, "w", encoding="utf-8", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["date", "channel", "net_amount"])
            for (date, channel) in sorted(totals.keys()):
                writer.writerow([date, channel, f"{totals[(date, channel)]:.2f}"])
    except OSError as e:
        sys.stderr.write(f"output error: {e}\n")
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
